use erp;
select * from erp.tbl_society_master where sc_sm_id='17735';
SELECT 
    MIN(id) AS id,
    batch_id,
    sc_sm_id,
    MIN(created_on),
    MAX(updated_on),
    SUM(CASE
        WHEN status = 'IN-QUEUE' THEN 1
        ELSE 0
    END) AS cnt_inqueue,
    SUM(CASE
        WHEN status = 'IN-PROGRESS' THEN 1
        ELSE 0
    END) AS cnt_inprogress,
    SUM(CASE
        WHEN status = 'COMPLETED' THEN 1
        ELSE 0
    END) AS cnt_completed,
    SUM(CASE
        WHEN status = 'FAILED' THEN 1
        ELSE 0
    END) AS cnt_failed,
    COUNT(id) AS total
FROM
    acc_bill_approval_process
WHERE
    (created_on BETWEEN '2025-12-01 10:00:00' AND '2026-01-03 00:00:00')
        AND id > 35309044
        AND batch_id > 1121664
GROUP BY batch_id
HAVING cnt_inqueue + cnt_inprogress> 0;

use erp;

SELECT 
    MIN(id) AS id,
    batch_id,
    sc_sm_id,
    MIN(created_on),
    MAX(updated_on),
    SUM(CASE
        WHEN status = 'IN-QUEUE' THEN 1
        ELSE 0
    END) AS cnt_inqueue,
    SUM(CASE
        WHEN status = 'IN-PROGRESS' THEN 1
        ELSE 0
    END) AS cnt_inprogress,
    SUM(CASE
        WHEN status = 'COMPLETED' THEN 1
        ELSE 0
    END) AS cnt_completed,
    SUM(CASE
        WHEN status = 'FAILED' THEN 1
        ELSE 0
    END) AS cnt_failed,
    COUNT(id) AS total
FROM
    acc_bill_approval_process
WHERE
    (created_on BETWEEN '2025-12-31 00:00:00' AND '2026-01-02 00:00:00')
        AND id > 37891608
        AND batch_id > 1160023
GROUP BY batch_id
HAVING cnt_inqueue + cnt_inprogress > 0;


